  "notes.promptSame": "The prompt files differ only in the data-id line used by the prompt panel and in the sentence describing how the HTML should be returned; the scene description itself is identical.",
  "notes.promptVariantsIntro": "One version's prompt text differs from the baseline. It is reproduced in full below:",
  "notes.promptVariants": "Prompt variant",
  "notes.promptFile": "Prompt file",
  "notes.versionsHeading": "Versions",
  "notes.versionsLead": "File size and line count come from that version's single index.html. Technique tags are detected with simple regular expressions: they mean the API appears in the source, not that the implementation is good.",
  "notes.table.model": "Model",
